const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function displayLink(v){if(!v)return '<span class="empty">—</span>';if(/^https:\/\/vt\.tokopedia\.com\/t\/[\w-]+\/$/.test(v))return `<a class="link" href="${esc(v)}" target="_blank" rel="noopener noreferrer">Buka link produk ↗</a>`;return `<span class="instruction">${esc(v)}</span>`;}
